using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;
namespace Touchfish {
public partial class PanelWindow {
 public void PreviewGvgClassScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;if(VerificationRun.Visual)VerifyGvgClassUi(folder);if(VerificationRun.Network)VerifyGvgClassTcp(folder);File.WriteAllText(Path.Combine(folder,"gvg-class-verification.txt"),"PASS: "+(checks-before)+" checks; actual WPF content and loopback TCP commands; not human mouse or two-machine testing.");}
 void VerifyGvgClassUi(string folder){
  ApplyTheme(true,true);ApplyMode(false);var prior=draft;try{draft=new DeckDocument{PoolId=GvgClassRules.PoolId,ClassId="MAGE"};
   var placeholders=catalog.BrowseDeckable("goblins-gnomes-2014");Check(placeholders.Count==51&&placeholders.All(c=>matchRules.Supports(c)),"All 51 upstream GvG neutral cards remain available");
   foreach(var c in placeholders){var row=CardLine(c,0,false);var grid=(Grid)row.Child;Check(!grid.Children.OfType<TextBlock>().Any(t=>t.Text.Contains("【暂不可用】")),"Neutral placeholder row clearly marked: "+c.Name);ShowDeckCard(c);Check(cardInfo.Text.Contains("可对战"),"Neutral details explicitly available: "+c.Name);}
   searchBox.Text="砰砰博士";showAllCards.IsChecked=true;versionPicker.SelectedIndex=0;RefreshCollection();ShowDeckCard(catalog.Card("GVG_110"));ShowPage("deck");Render(Path.Combine(folder,"gvg-neutral-available.png"));Check(filteredCards.Any(c=>c.Id=="GVG_110"),"Dr Boom discoverable in collection search");
   ShowDeckCard(catalog.Card("GVG_003"));Check(cardInfo.Text.Contains("可对战"),"New class card marked playable");
   match=new MatchEngine(catalog,matchRules.TrainingDeck("DRUID"),matchRules.TrainingDeck("MAGE"),42,true);match.MarkMulliganCompleteForTests();foreach(var p in match.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}match.Players[0].ClassId="DRUID";matchViewSeat=0;localTest=true;awaitHandoff=false;
   ShowPage("match");int cub=NaxxUiHand(match,"GVG_030");BeginCard(cub);ClickEmptySlot(0,0);Check(ChoicePending()&&match.Rules.Choices(match.Card("GVG_030")).Length==2,"GvG minion opens two-option choice UI");Render(Path.Combine(folder,"gvg-choose-one.png"));SelectChoice("health");Check(match.Players[0].Board.Any(u=>u.CardId=="GVG_030"&&u.MaxHealth==3),"GvG choice applies through WPF workflow");
   ApplyMode(true);searchBox.Text="砰砰博士";RefreshCollection();ShowPage("deck");Render(Path.Combine(folder,"gvg-neutral-minimal.png"));Check(Width==392&&Height==300,"GvG placeholders retain minimal size");ApplyMode(false);
  }finally{draft=prior;localTest=false;ClearPending();}
 }
 void GvgTcpReset(int active){var g=lanAuthority.Game;g.Active=active;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;p.Health=30;p.Armor=0;p.PowerUsed=false;p.ClassId="MAGE";p.Deck.Clear();p.Deck.AddRange(Enumerable.Repeat("VAN_CS2_182",10));}ClearPending();}
 void VerifyGvgClassTcp(string folder){LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetEffectsLevel(EffectLevel.Off);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);guest.SetEffectsLevel(EffectLevel.Off);try{
  lanPort.Text=FreeLanPort().ToString();lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");lanDeck.SelectedIndex=0;BeginLan(true);guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");guest.lanDeck.SelectedIndex=0;guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"GvG peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"GvG host opening");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"GvG both opening hands confirmed");var g=lanAuthority.Game;
  GvgTcpReset(0);int bolvar=NaxxUiHand(g,"GVG_063",1);var victim=g.Summon(1,"VAN_CS2_171");int fire=NaxxUiHand(g,"VAN_CS2_029",0);PublishLan();DoMatch("play",fire,new MatchTarget(1,victim.Id));PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==bolvar&&h.AttackBonus==1),"Private hand growth arrives at owner");Check(LanProtocol.View(g,0,"gvg",1).Players[1].Hand.Length==0,"Host-facing snapshot has no guest hand growth identities");
  GvgTcpReset(1);g.Players[1].ClassId="MAGE";int portal=NaxxUiHand(g,"GVG_003",1);PublishLan();PumpLan(()=>guest.match.Active==1&&guest.match.Players[1].Hand.Any(h=>h.Id==portal),"Guest Portal private hand");guest.BeginCard(portal);PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].Hand.Any(h=>h.CostAdjustment==-3),"Guest casts Portal through TCP");Check(guest.match.Players[1].Hand.Single().Generated&&LanProtocol.View(g,0,"gvg",1).Players[1].Hand.Length==0,"Generated discounted minion stays private");
  GvgTcpReset(1);g.Players[1].ClassId="HUNTER";g.Summon(1,"GVG_087");victim=g.Summon(1,"VAN_CS2_182");PublishLan();PumpLan(()=>guest.match.Players[1].Board.Any(u=>u.Id==victim.Id)&&guest.match.PowerNeedsTarget(1),"Sniper targetable power synchronized");guest.BeginPower();guest.ClickMatchTarget(new MatchTarget(1,victim.Id));PumpLan(()=>!guest.lanWaiting&&guest.match.Unit(new MatchTarget(1,victim.Id)).Health==3,"Sniper power targets friendly minion through TCP");Check(g.Players[1].PowerUsed&&g.Players[1].Mana==8,"Sniper power consumes ordinary resources");
  GvgTcpReset(1);int juggernaut=NaxxUiHand(g,"GVG_056",1);g.Players[1].ClassId="WARRIOR";PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==juggernaut),"Juggernaut arrives");guest.BeginCard(juggernaut);guest.ClickEmptySlot(1,0);PumpLan(()=>!guest.lanWaiting&&g.Players[0].Deck.Contains("GVG_056t"),"Guest shuffles mine through TCP");Check(!JsonData.Serializer().Serialize(LanProtocol.View(g,1,"gvg",1)).Contains("GVG_056t"),"Enemy deck mine identity not in private wire fields");
  g.Active=0;g.Players[0].Deck.Clear();g.Players[0].Deck.AddRange(new[]{"GVG_056t","VAN_CS2_182","VAN_CS2_182"});int draw=NaxxUiHand(g,"VAN_CS2_023",0);PublishLan();DoMatch("play",draw);PumpLan(()=>guest.match.Players[0].Health==20&&guest.match.Players[0].HandCount==2,"Mine damage and replacement draw synchronized");Check(g.Players[0].Hand.Count==2&&g.Players[0].Hand.All(h=>h.CardId=="VAN_CS2_182"),"Mine replaced itself without becoming a hand card");
  GvgTcpReset(1);g.Players[1].ClassId="DRUID";int choice=NaxxUiHand(g,"GVG_030",1);PublishLan();PumpLan(()=>guest.match.Active==1&&guest.match.Players[1].Hand.Any(h=>h.Id==choice),"Guest GvG choose one hand");guest.BeginCard(choice);guest.ClickEmptySlot(1,0);Check(guest.ChoicePending(),"Guest GvG choice UI available");guest.SelectChoice("attack");PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].Board.Any(u=>u.CardId=="GVG_030"),"GvG choice reaches authority through TCP");Check(g.AttackValue(g.Players[1].Board.Single())==3&&guest.match.Players[1].Board.Single().Taunt,"GvG choice stats synchronized");
  GvgTcpReset(1);g.Players[1].ClassId="PALADIN";g.Summon(1,"GVG_104");int grown=NaxxUiHand(g,"GVG_063",1);g.Players[1].Hand.Single(h=>h.Id==grown).AttackBonus=4;PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==grown&&h.AttackBonus==4),"Grown Bolvar stays private before play");guest.BeginCard(grown);guest.ClickEmptySlot(1,1);PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].Board.Any(u=>u.CardId=="GVG_063"),"Grown Bolvar enters through guest commands");var grownBody=guest.match.Players[1].Board.Single(u=>u.CardId=="GVG_063");Check(guest.match.AttackValue(grownBody)==5&&grownBody.MaxHealth==7,"Network Bolvar transfers hand growth before Hobgoblin and receives no false buff");
  GvgTcpReset(1);g.Players[1].ClassId="SHAMAN";g.Summon(1,"GVG_058");g.Equip(1,"GVG_036");int replacement=NaxxUiHand(g,"GVG_036",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==replacement),"Replacement Powermace reaches guest");guest.BeginCard(replacement);PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].Board.Single().MaxHealth==4,"Weapon replacement deathrattle synchronizes");Check(g.Players[1].Board.Single().BuffAttack==2&&guest.match.Players[1].WeaponDurability==2,"Replacement triggers old weapon once and retains new weapon");
  GvgTcpReset(0);g.Players[0].ClassId="WARLOCK";g.Players[0].Armor=5;g.Summon(0,"GVG_100");int hellfire=NaxxUiHand(g,"VAN_CS2_062");PublishLan();DoMatch("play",hellfire);PumpLan(()=>guest.match.Players[0].Armor==2&&guest.match.Players[0].Board.Single().MaxHealth==6,"Armor damage Watcher buff synchronizes");Check(guest.match.Players[0].Health==30&&guest.match.AttackValue(guest.match.Players[0].Board.Single())==6,"Both clients preserve health while armor damage triggers growth");
  guest.Opacity=1;guest.Render(Path.Combine(folder,"gvg-lan-choice-result.png"));guest.Opacity=0;
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}
}

